import { createContext, useContext, useState, useEffect, useMemo, ReactNode } from "react";
import { Platform } from "react-native";
import { db } from "@/lib/db";
import { authAdapter } from "@/lib/auth";
import * as Google from "expo-auth-session/providers/google";
import * as WebBrowser from "expo-web-browser";
import {
  getAuthErrorMessage,
  mapFirebaseError,
  generateUniqueUsername,
} from "@/lib/auth/utils";
import { queryClient } from "@/lib/query-client";
import { clearAllMemCache, clearAllAsyncStorageCache } from "@/services/cache/qr-cache";
import { clearAllAnonymousSessions } from "@/services/cache/anonymous-session";
import { validateEmail } from "@/shared/utils/email-validator";

const SERVER_BASE_URL = process.env.EXPO_PUBLIC_DOMAIN
  ? `https://${process.env.EXPO_PUBLIC_DOMAIN}`
  : __DEV__
    ? "http://localhost:5000"
    : "";

async function serverValidateEmail(email: string): Promise<{ valid: boolean; reason?: string }> {
  try {
    const res = await fetch(`${SERVER_BASE_URL}/api/validate-email`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });
    if (!res.ok) return { valid: false, reason: "Email validation failed. Please try again." };
    return await res.json();
  } catch {
    return validateEmail(email);
  }
}

WebBrowser.maybeCompleteAuthSession();

const GOOGLE_WEB_CLIENT_ID = process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID ?? "";
const GOOGLE_ANDROID_CLIENT_ID = process.env.EXPO_PUBLIC_ANDROID_CLIENT_ID ?? "";

let GoogleSignin: any = null;
let statusCodes: any = null;

if (Platform.OS !== "web") {
  try {
    const mod = require("@react-native-google-signin/google-signin");
    GoogleSignin = mod.GoogleSignin;
    statusCodes = mod.statusCodes;
    GoogleSignin.configure({
      webClientId: GOOGLE_WEB_CLIENT_ID,
      forceCodeForRefreshToken: true,
      offlineAccess: false,
    });
  } catch {
    GoogleSignin = null;
    statusCodes = null;
  }
}

interface AuthUser {
  id: string;
  email: string;
  displayName: string;
  photoURL?: string | null;
  emailVerified: boolean;
  username?: string;
}

interface AuthContextValue {
  user: AuthUser | null;
  token: string | null;
  isLoading: boolean;
  signIn: (email: string, password: string) => Promise<void>;
  signUp: (email: string, displayName: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
  signInWithGoogle: () => Promise<void>;
  switchGoogleAccount: () => Promise<void>;
  sendPasswordReset: (email: string) => Promise<void>;
  resendVerification: () => Promise<void>;
  refreshUser: () => Promise<void>;
  updateLocalDisplayName: (name: string) => void;
  googleRequest: ReturnType<typeof Google.useAuthRequest>[0];
}

const AuthContext = createContext<AuthContextValue | null>(null);

export { getAuthErrorMessage };

async function reserveUsername(uid: string, displayName: string): Promise<string> {
  for (let attempt = 0; attempt < 5; attempt++) {
    const candidate = await generateUniqueUsername(displayName);
    try {
      await db.set(["usernames", candidate], { userId: uid, reservedAt: db.timestamp() });
      return candidate;
    } catch {
    }
  }
  const fallback = "user" + uid.slice(-8).toLowerCase().replace(/[^a-z0-9]/g, "x");
  try { await db.set(["usernames", fallback], { userId: uid, reservedAt: db.timestamp() }); } catch {}
  return fallback;
}

async function syncUserToDb(uid: string, email: string | null, displayName: string | null, photoURL: string | null, overrideName?: string) {
  try {
    const userData = await db.get(["users", uid]);
    if (!userData) {
      const name = overrideName || displayName || email?.split("@")[0] || "User";
      const username = await reserveUsername(uid, name);
      await db.set(["users", uid], {
        uid,
        email,
        displayName: name,
        photoURL: photoURL || null,
        isDeleted: false,
        createdAt: db.timestamp(),
        username,
      });
    } else if (userData.isDeleted) {
      throw new Error("ACCOUNT_DELETED");
    } else if (!userData.username) {
      const name = overrideName || displayName || userData.displayName || "User";
      const username = await reserveUsername(uid, name);
      await db.update(["users", uid], { username });
    }
  } catch (e: any) {
    if (e.message === "ACCOUNT_DELETED") throw new Error("This account has been deleted.");
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [googleRequest, googleResponse, promptGoogleAsync] = Google.useAuthRequest({
    webClientId: GOOGLE_WEB_CLIENT_ID,
    androidClientId: GOOGLE_ANDROID_CLIENT_ID,
    scopes: ["profile", "email"],
  })
  useEffect(() => {
    const unsubscribe = authAdapter.onIdTokenChanged(async (adapterUser) => {
      if (adapterUser) {
        if (!adapterUser.emailVerified) {
          setUser(null);
          setToken(null);
          setIsLoading(false);
          return;
        }
        try {
          const idToken = await adapterUser.getIdToken();
          const authUser: AuthUser = {
            id: adapterUser.uid,
            email: adapterUser.email ?? "",
            displayName: adapterUser.displayName ?? adapterUser.email?.split("@")[0] ?? "User",
            photoURL: adapterUser.photoURL,
            emailVerified: adapterUser.emailVerified,
          };
          setUser(authUser);
          setToken(idToken);
          setIsLoading(false);
          queryClient.prefetchQuery({
            queryKey: ["userProfile", adapterUser.uid],
            queryFn: async () => {
              const userData = await db.get(["users", adapterUser.uid]);
              if (userData) {
                setUser((prev) => {
                  if (!prev || prev.id !== adapterUser.uid) return prev;
                  return {
                    ...prev,
                    username: (userData.username as string) || prev.username,
                    photoURL: (userData.photoURL as string) || prev.photoURL,
                  };
                });
              }
              return userData;
            },
            staleTime: 5 * 60 * 1000,
          });
        } catch {
          setUser(null);
          setToken(null);
          setIsLoading(false);
        }
      } else {
        setUser(null);
        setToken(null);
        setIsLoading(false);
        queryClient.removeQueries({ queryKey: ["userProfile"] });
      }
    });
    return unsubscribe;
  }, []);

  useEffect(() => {
    if (Platform.OS !== "web" && GoogleSignin) {
      GoogleSignin.signInSilently()
        .then(async (result: any) => {
          if (result?.type === "success" && result?.data?.idToken) {
            try {
              const adapterUser = await authAdapter.signInWithGoogleIdToken(result.data.idToken);
              await syncUserToDb(adapterUser.uid, adapterUser.email, adapterUser.displayName, adapterUser.photoURL);
            } catch {}
          }
        })
        .catch(() => {});
    }
  }, []);

  useEffect(() => {
    if (Platform.OS === "web" && googleResponse?.type === "success") {
      const { authentication } = googleResponse;
      if (authentication?.accessToken) {
        handleGoogleAccessToken(authentication.accessToken);
      }
    }
  }, [googleResponse]);

  async function signIn(email: string, password: string) {
    try {
      const adapterUser = await authAdapter.signIn(email, password);
      if (!adapterUser.emailVerified) {
        const err = new Error(getAuthErrorMessage("auth/email-not-verified")) as any;
        err.code = "auth/email-not-verified";
        throw err;
      }
      await syncUserToDb(adapterUser.uid, adapterUser.email, adapterUser.displayName, adapterUser.photoURL);
      const idToken = await adapterUser.getIdToken();
      setUser({
        id: adapterUser.uid,
        email: adapterUser.email ?? "",
        displayName: adapterUser.displayName ?? adapterUser.email?.split("@")[0] ?? "User",
        photoURL: adapterUser.photoURL,
        emailVerified: adapterUser.emailVerified,
      });
      setToken(idToken);
    } catch (e: any) {
      if (e.code === "auth/email-not-verified") throw e;
      throw mapFirebaseError(e);
    }
  }

  async function signUp(email: string, displayName: string, password: string) {
    try {
      const emailValidation = await serverValidateEmail(email);
      if (!emailValidation.valid) {
        const err = new Error(emailValidation.reason || "Please use a real email address.") as any;
        err.code = "auth/invalid-email-domain";
        throw err;
      }

      const adapterUser = await authAdapter.signUp(email, password);
      await authAdapter.updateDisplayName(adapterUser, displayName);
      await authAdapter.sendVerificationEmail(adapterUser);
      await authAdapter.signOut();
      const err = new Error("VERIFICATION_SENT") as any;
      err.code = "auth/verification-sent";
      throw err;
    } catch (e: any) {
      if (e.code === "auth/verification-sent") throw e;
      if (e.code === "auth/invalid-email-domain") throw e;
      throw mapFirebaseError(e);
    }
  }

  async function handleGoogleAccessToken(accessToken: string) {
    try {
      const adapterUser = await authAdapter.signInWithGoogleToken(accessToken);
      const idToken = await adapterUser.getIdToken();
      setUser({
        id: adapterUser.uid,
        email: adapterUser.email ?? "",
        displayName: adapterUser.displayName ?? adapterUser.email?.split("@")[0] ?? "User",
        photoURL: adapterUser.photoURL,
        emailVerified: adapterUser.emailVerified,
      });
      setToken(idToken);
      syncUserToDb(adapterUser.uid, adapterUser.email, adapterUser.displayName, adapterUser.photoURL).catch(() => {});
    } catch (e: any) {
      throw mapFirebaseError(e);
    }
  }

  async function handleGoogleIdToken(idToken: string) {
    const adapterUser = await authAdapter.signInWithGoogleIdToken(idToken);
    const firebaseToken = await adapterUser.getIdToken();
    setUser({
      id: adapterUser.uid,
      email: adapterUser.email ?? "",
      displayName: adapterUser.displayName ?? adapterUser.email?.split("@")[0] ?? "User",
      photoURL: adapterUser.photoURL,
      emailVerified: adapterUser.emailVerified,
    });
    setToken(firebaseToken);
    syncUserToDb(adapterUser.uid, adapterUser.email, adapterUser.displayName, adapterUser.photoURL).catch(() => {});
  }

  async function signInWithGoogle() {
    if (Platform.OS !== "web" && GoogleSignin) {
      try {
        const silentResult = await GoogleSignin.signInSilently();
        if (silentResult?.type === "success" && silentResult?.data?.idToken) {
          try {
            await handleGoogleIdToken(silentResult.data.idToken);
            return;
          } catch {}
        }
      } catch {}
      const result = await GoogleSignin.signIn();
      if (result.type === "success" && result.data?.idToken) {
        try {
          await handleGoogleIdToken(result.data.idToken);
        } catch (e: any) {
          throw mapFirebaseError(e);
        }
      } else if (result.type === "cancelled") {
        const err = new Error(getAuthErrorMessage("auth/popup-closed-by-user"));
        throw err;
      }
    } else {
      await promptGoogleAsync();
    }
  }

  async function switchGoogleAccount() {
    if (Platform.OS !== "web" && GoogleSignin) {
      try {
        await GoogleSignin.signOut();
      } catch {}
      await signInWithGoogle();
    } else {
      await signInWithGoogle();
    }
  }

  async function signOut() {
    try {
      const AsyncStorage = (await import("@react-native-async-storage/async-storage")).default;
      if (user?.id) {
        await AsyncStorage.removeItem(`local_scan_history_${user.id}`);
      }
      const allKeys = await AsyncStorage.getAllKeys();
      const qrContentKeys = allKeys.filter((k) => k.startsWith("qr_content_"));
      if (qrContentKeys.length > 0) await AsyncStorage.multiRemove(qrContentKeys);
      await AsyncStorage.removeItem("qrguard_downloads_dir_uri");
    } catch {}
    clearAllMemCache();
    clearAllAnonymousSessions();
    await clearAllAsyncStorageCache();
    queryClient.clear();
    try {
      if (Platform.OS !== "web" && GoogleSignin) {
        await GoogleSignin.signOut().catch(() => {});
      }
      await authAdapter.signOut();
    } catch {}
    setUser(null);
    setToken(null);
  }

  async function sendPasswordReset(email: string) {
    try {
      await authAdapter.sendPasswordReset(email);
    } catch (e: any) {
      throw mapFirebaseError(e);
    }
  }

  async function resendVerification() {
    try {
      const currentUser = authAdapter.getCurrentUser();
      if (currentUser) await authAdapter.sendVerificationEmail(currentUser);
    } catch (e: any) {
      throw mapFirebaseError(e);
    }
  }

  function updateLocalDisplayName(name: string) {
    setUser((prev) => prev ? { ...prev, displayName: name } : prev);
  }

  async function refreshUser() {
    const currentUser = authAdapter.getCurrentUser();
    if (!currentUser) return;
    try {
      await currentUser.reload();
      const reloaded = authAdapter.getCurrentUser();
      if (reloaded) {
        if (reloaded.emailVerified) {
          try {
            const freshToken = await reloaded.getIdToken(true);
            setToken(freshToken);
          } catch {}
          await syncUserToDb(
            reloaded.uid,
            reloaded.email,
            reloaded.displayName,
            reloaded.photoURL,
          ).catch(() => {});
        }
        const authUser: AuthUser = {
          id: reloaded.uid,
          email: reloaded.email ?? "",
          displayName: reloaded.displayName ?? reloaded.email?.split("@")[0] ?? "User",
          photoURL: reloaded.photoURL,
          emailVerified: reloaded.emailVerified,
        };
        if (reloaded.emailVerified) {
          try {
            await db.update(["users", reloaded.uid], {
              displayName: reloaded.displayName || "",
              photoURL: reloaded.photoURL || null,
            });
          } catch {}
          try {
            const userData = await db.get(["users", reloaded.uid]);
            if (userData?.username) authUser.username = userData.username as string;
          } catch {}
        }
        setUser(authUser);
      }
    } catch {}
  }

  const value = useMemo(
    () => ({
      user,
      token,
      isLoading,
      signIn,
      signUp,
      signOut,
      signInWithGoogle,
      switchGoogleAccount,
      sendPasswordReset,
      resendVerification,
      refreshUser,
      updateLocalDisplayName,
      googleRequest,
    }),
    [user, token, isLoading, googleRequest]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}

import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo,
} from "react";
import { useColorScheme } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as SystemUI from "expo-system-ui";
import Colors, { type AppColors } from "@/shared/constants/colors";

type ThemeMode = "system" | "dark" | "light";

interface ThemeContextValue {
  colors: AppColors;
  isDark: boolean;
  mode: ThemeMode;
  setMode: (m: ThemeMode) => void;
  toggleTheme: () => void;
}

const STORAGE_KEY = "qrguard_theme_mode";

const ThemeContext = createContext<ThemeContextValue>({
  colors: Colors.dark,
  isDark: true,
  mode: "system",
  setMode: () => {},
  toggleTheme: () => {},
});

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const systemScheme = useColorScheme();
  const [mode, setModeState] = useState<ThemeMode>("system");
  const [ready, setReady] = useState(false);

  useEffect(() => {
    AsyncStorage.getItem(STORAGE_KEY)
      .then((stored) => {
        if (stored === "dark" || stored === "light" || stored === "system") {
          setModeState(stored as ThemeMode);
        }
      })
      .catch(() => {})
      .finally(() => setReady(true));
  }, []);

  const setMode = useCallback((m: ThemeMode) => {
    setModeState(m);
    AsyncStorage.setItem(STORAGE_KEY, m).catch(() => {});
  }, []);

  const toggleTheme = useCallback(() => {
    const next = mode === "dark" ? "light" : "dark";
    setMode(next);
  }, [mode, setMode]);

  const effectiveIsDark =
    mode === "system" ? systemScheme === "dark" : mode === "dark";

  const colors = effectiveIsDark ? Colors.dark : Colors.light;

  useEffect(() => {
    SystemUI.setBackgroundColorAsync(colors.background).catch(() => {});
  }, [colors.background]);

  const contextValue = useMemo(
    () => ({ colors, isDark: effectiveIsDark, mode, setMode, toggleTheme }),
    [colors, effectiveIsDark, mode, setMode, toggleTheme]
  );

  if (!ready) return null;

  return (
    <ThemeContext.Provider value={contextValue}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  return useContext(ThemeContext);
}

/**
 * AvatarContext — centralised, zero-duplicate-fetch avatar store.
 *
 * Responsibilities:
 *  1. Persist the latest avatar URL + a version timestamp in AsyncStorage so the
 *     image is available synchronously on the next app launch (before any network call).
 *  2. Expose `cachedUrl` (url?v=<version>) so expo-image cache-busts ONLY when
 *     the photo actually changes — not on every navigation.
 *  3. Provide `setAvatar(url)` for optimistic updates after upload, and `syncAvatar(url)`
 *     for quiet background syncs (profile loads, login) that skip a version bump when
 *     the URL hasn't changed.
 *  4. `clearAvatar()` is called on sign-out so no stale data leaks across users.
 *
 * No new packages needed — Context + AsyncStorage + expo-image cachePolicy covers it.
 */

import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";

const AVATAR_URL_KEY = "qrg:avatar:url";
const AVATAR_VER_KEY = "qrg:avatar:version";

interface AvatarState {
  url: string | null;
  version: number;
  cachedUrl: string | null;
  setAvatar: (url: string) => void;
  syncAvatar: (url: string | null) => void;
  clearAvatar: () => void;
}

const AvatarContext = createContext<AvatarState>({
  url: null,
  version: 0,
  cachedUrl: null,
  setAvatar: () => {},
  syncAvatar: () => {},
  clearAvatar: () => {},
});

export function AvatarProvider({ children }: { children: React.ReactNode }) {
  const [url, setUrl] = useState<string | null>(null);
  const [version, setVersion] = useState(0);

  useEffect(() => {
    AsyncStorage.multiGet([AVATAR_URL_KEY, AVATAR_VER_KEY]).then((pairs) => {
      const storedUrl = pairs[0][1];
      const storedVer = pairs[1][1];
      if (storedUrl) setUrl(storedUrl);
      if (storedVer) setVersion(Number(storedVer));
    }).catch(() => {});
  }, []);

  const setAvatar = useCallback((newUrl: string) => {
    const v = Date.now();
    setUrl(newUrl);
    setVersion(v);
    AsyncStorage.multiSet([
      [AVATAR_URL_KEY, newUrl],
      [AVATAR_VER_KEY, String(v)],
    ]).catch(() => {});
  }, []);

  const syncAvatar = useCallback((newUrl: string | null) => {
    if (!newUrl) return;
    setUrl((prev) => {
      if (prev === newUrl) return prev;
      const v = Date.now();
      setVersion(v);
      AsyncStorage.multiSet([
        [AVATAR_URL_KEY, newUrl],
        [AVATAR_VER_KEY, String(v)],
      ]).catch(() => {});
      return newUrl;
    });
  }, []);

  const clearAvatar = useCallback(() => {
    setUrl(null);
    setVersion(0);
    AsyncStorage.multiRemove([AVATAR_URL_KEY, AVATAR_VER_KEY]).catch(() => {});
  }, []);

  const cachedUrl = useMemo(() => (url ? `${url}?v=${version}` : null), [url, version]);

  const contextValue = useMemo(
    () => ({ url, version, cachedUrl, setAvatar, syncAvatar, clearAvatar }),
    [url, version, cachedUrl, setAvatar, syncAvatar, clearAvatar]
  );

  return (
    <AvatarContext.Provider value={contextValue}>
      {children}
    </AvatarContext.Provider>
  );
}

export function useAvatar() {
  return useContext(AvatarContext);
}

