import { Router, type Request, type Response } from "express";
import { decodeQrFromImage } from "../image-decode";
import { validateEmail } from "../../shared/utils/email-validator";
import { validateQrContent } from "../../services/analysis/qr-validator";
import { checkRateLimit, getClientIp } from "../middleware/rate-limiter";

export const securityRouter = Router();

// POST /api/v1/validate-email
securityRouter.post("/validate-email", (req: Request, res: Response) => {
  const { email } = req.body;
  if (!email || typeof email !== "string") {
    return res.status(400).json({ valid: false, reason: "Email is required." });
  }
  return res.json(validateEmail(email.trim()));
});

// POST /api/v1/qr/decode-image
securityRouter.post("/qr/decode-image", async (req: Request, res: Response) => {
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ") || authHeader.length < 16) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const ip = getClientIp(req);
  const allowed = await checkRateLimit(ip);
  if (!allowed) {
    return res.status(429).json({ message: "Too many requests. Please wait a minute and try again." });
  }

  try {
    const { imageBase64 } = req.body;
    if (!imageBase64 || typeof imageBase64 !== "string") {
      return res.status(400).json({ message: "Image required" });
    }
    if (imageBase64.length > 5 * 1024 * 1024) {
      return res.status(413).json({ message: "Image too large" });
    }

    const content = await decodeQrFromImage(imageBase64);
    if (!content) return res.status(404).json({ message: "No QR code found in image" });

    const validation = validateQrContent(content);
    if (!validation.valid) {
      return res.status(422).json({
        message: validation.error || "QR content rejected by safety check",
        code: "QR_VALIDATION_FAILED",
      });
    }

    return res.json({ content, kind: validation.kind });
  } catch (e: any) {
    console.error("[v1/decode-image] error:", e);
    return res.status(500).json({ message: "Image decode failed" });
  }
});

import { Router, type Request, type Response } from "express";
import * as admin from "firebase-admin";

export const qrRouter = Router();

function getAdminApp(): admin.app.App | null {
  try {
    if (admin.apps.length > 0) return admin.apps[0]!;
    const serviceAccount = process.env.FIREBASE_SERVICE_ACCOUNT_JSON;
    if (!serviceAccount) return null;
    return admin.initializeApp({
      credential: admin.credential.cert(JSON.parse(serviceAccount)),
    });
  } catch {
    return null;
  }
}

// PATCH /api/v1/qr/:qrId/active  — toggle QR active/paused state
qrRouter.patch("/:qrId/active", async (req: Request, res: Response) => {
  const { qrId } = req.params;
  const { isActive, deactivationMessage } = req.body;

  if (!qrId) return res.status(400).json({ error: "Invalid QR code ID" });
  if (typeof isActive !== "boolean") return res.status(400).json({ error: "isActive must be a boolean" });

  const authHeader = req.headers["authorization"];
  if (!authHeader?.startsWith("Bearer ")) return res.status(401).json({ error: "Unauthorized" });

  const adminApp = getAdminApp();
  if (!adminApp) {
    return res.status(503).json({ error: "Server not configured. Set FIREBASE_SERVICE_ACCOUNT_JSON." });
  }

  try {
    const decodedToken = await admin.auth(adminApp).verifyIdToken(authHeader.slice(7));
    const uid = decodedToken.uid;

    const db = admin.firestore(adminApp);
    const docRef = db.collection("qrCodes").doc(qrId);
    const docSnap = await docRef.get();

    if (!docSnap.exists) return res.status(404).json({ error: "QR code not found" });
    if (docSnap.data()?.ownerId !== uid) return res.status(403).json({ error: "Forbidden" });

    const updateData: Record<string, any> = {
      isActive,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    };
    if (!isActive && deactivationMessage) {
      updateData.deactivationMessage = deactivationMessage;
    }
    if (isActive) {
      updateData.deactivationMessage = null;
    }

    await docRef.update(updateData);
    return res.json({ success: true, isActive });
  } catch (e: any) {
    if (e.code === "auth/argument-error" || e.code === "auth/id-token-expired") {
      return res.status(401).json({ error: "Invalid or expired token" });
    }
    console.error("[v1/qr/active] error:", e);
    return res.status(500).json({ error: "Failed to update QR code" });
  }
});

// GET /api/v1/qr/:uuid/analytics  — aggregated scan analytics (owner-only)
qrRouter.get("/:uuid/analytics", async (req: Request, res: Response) => {
  const { uuid } = req.params;
  const authHeader = req.headers["authorization"];
  if (!authHeader?.startsWith("Bearer ")) return res.status(401).json({ error: "Unauthorized" });

  const adminApp = getAdminApp();
  if (!adminApp) {
    return res.status(503).json({ error: "Server not configured. Set FIREBASE_SERVICE_ACCOUNT_JSON." });
  }

  try {
    const decodedToken = await admin.auth(adminApp).verifyIdToken(authHeader.slice(7));
    const uid = decodedToken.uid;

    const db = admin.firestore(adminApp);

    // Resolve qrDocId: try direct doc by id, then by uuid field
    let qrDocId: string | null = null;
    const directDoc = await db.collection("qrCodes").doc(uuid).get();
    if (directDoc.exists && directDoc.data()?.ownerId === uid) {
      qrDocId = uuid;
    } else {
      const q = await db.collection("qrCodes").where("uuid", "==", uuid).limit(1).get();
      if (!q.empty && q.docs[0].data().ownerId === uid) {
        qrDocId = q.docs[0].id;
      }
    }

    if (!qrDocId) {
      return res.status(403).json({ error: "QR code not found or you do not own it" });
    }

    const eventsSnap = await db
      .collection("qrCodes").doc(qrDocId).collection("events")
      .orderBy("timestamp", "desc")
      .limit(2000)
      .get();

    const now = Date.now();
    const MS_7D  = 7  * 24 * 60 * 60 * 1000;
    const MS_30D = 30 * 24 * 60 * 60 * 1000;

    let scans7d = 0;
    let scans30d = 0;
    const trend7d    = new Array(7).fill(0);
    const platformBreakdown = { android: 0, ios: 0, web: 0, unknown: 0 };
    const verdictBreakdown  = { safe: 0, flagged: 0, unknown: 0 };
    const topHours   = new Array(24).fill(0);

    for (const doc of eventsSnap.docs) {
      const d = doc.data();
      const ts: number = d.timestamp?.toDate?.()?.getTime?.() ?? now;
      const age = now - ts;

      if (age < MS_7D) {
        scans7d++;
        trend7d[Math.min(6, Math.floor(age / 86_400_000))]++;
      }
      if (age < MS_30D) scans30d++;

      const plat = d.platform || "unknown";
      if (plat in platformBreakdown) (platformBreakdown as any)[plat]++;
      else platformBreakdown.unknown++;

      const ver = d.verdict || "unknown";
      if (ver in verdictBreakdown) (verdictBreakdown as any)[ver]++;
      else verdictBreakdown.unknown++;

      topHours[new Date(ts).getHours()]++;
    }

    return res.json({
      totalScans: eventsSnap.size,
      scans7d,
      scans30d,
      trend7d,
      platformBreakdown,
      verdictBreakdown,
      topHours,
      cachedAt: now,
    });
  } catch (e: any) {
    if (e.code === "auth/argument-error" || e.code === "auth/id-token-expired") {
      return res.status(401).json({ error: "Invalid or expired token" });
    }
    console.error("[v1/qr/analytics] error:", e);
    return res.status(500).json({ error: "Analytics query failed" });
  }
});

import { Router, type Request, type Response } from "express";
import crypto from "crypto";
import * as admin from "firebase-admin";

export const paymentsRouter = Router();

let razorpay: any = null;

async function getRazorpay() {
  if (razorpay) return razorpay;
  const keyId = process.env.RAZORPAY_KEY_ID;
  const keySecret = process.env.RAZORPAY_KEY_SECRET;
  if (!keyId || !keySecret) return null;
  const Razorpay = (await import("razorpay")).default;
  razorpay = new Razorpay({ key_id: keyId, key_secret: keySecret });
  return razorpay;
}

function getFirestoreAdmin(): admin.firestore.Firestore | null {
  try {
    if (!admin.apps.length) {
      const serviceAccount = process.env.FIREBASE_SERVICE_ACCOUNT_JSON;
      if (!serviceAccount) return null;
      admin.initializeApp({ credential: admin.credential.cert(JSON.parse(serviceAccount)) });
    }
    return admin.firestore();
  } catch {
    return null;
  }
}

// POST /api/v1/donation/create-order
paymentsRouter.post("/create-order", async (req: Request, res: Response) => {
  try {
    const rzp = await getRazorpay();
    if (!rzp) return res.status(503).json({ error: "Payment service not configured" });

    const { amount, currency = "INR", donorName, donorEmail, userId } = req.body;
    if (!amount || typeof amount !== "number" || amount < 1) {
      return res.status(400).json({ error: "Invalid amount" });
    }

    const order = await rzp.orders.create({
      amount: amount * 100,
      currency,
      receipt: `donation_${Date.now()}`,
      notes: {
        donorName: donorName || "Anonymous",
        donorEmail: donorEmail || "",
        userId: userId || "",
        type: "charity",
      },
    });

    return res.json({
      orderId: order.id,
      amount: order.amount,
      currency: order.currency,
      keyId: process.env.RAZORPAY_KEY_ID,
    });
  } catch (err: any) {
    console.error("[v1/donation] create-order error:", err);
    return res.status(500).json({ error: "Failed to create order" });
  }
});

// POST /api/v1/donation/verify
paymentsRouter.post("/verify", async (req: Request, res: Response) => {
  try {
    const {
      razorpay_order_id, razorpay_payment_id, razorpay_signature,
      amount, currency, donorName, donorEmail, userId,
    } = req.body;

    const keySecret = process.env.RAZORPAY_KEY_SECRET;
    if (!keySecret) return res.status(503).json({ error: "Service not configured" });

    const expected = crypto
      .createHmac("sha256", keySecret)
      .update(`${razorpay_order_id}|${razorpay_payment_id}`)
      .digest("hex");

    if (expected !== razorpay_signature) {
      return res.status(400).json({ error: "Payment verification failed" });
    }

    const db = getFirestoreAdmin();
    if (db) {
      await db.collection("donations").add({
        orderId: razorpay_order_id,
        paymentId: razorpay_payment_id,
        amount: amount / 100,
        currency: currency || "INR",
        donorName: donorName || "Anonymous",
        donorEmail: donorEmail || "",
        userId: userId || null,
        status: "success",
        paidAt: admin.firestore.FieldValue.serverTimestamp(),
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    }

    return res.json({ success: true, paymentId: razorpay_payment_id });
  } catch (err: any) {
    console.error("[v1/donation] verify error:", err);
    return res.status(500).json({ error: "Verification failed" });
  }
});

import type { Express } from "express";
import { securityRouter } from "./security";
import { qrRouter } from "./qr";
import { paymentsRouter } from "./payments";

/**
 * Registers all versioned API routes under /api/v1/.
 *
 * Route layout:
 *   /api/v1/validate-email       POST  — email validator
 *   /api/v1/qr/decode-image      POST  — server-side QR image decode
 *   /api/v1/qr/:qrId/active      PATCH — toggle QR active state
 *   /api/v1/qr/:uuid/analytics   GET   — aggregated analytics (owner-only)
 *   /api/v1/donation/create-order POST — Razorpay order
 *   /api/v1/donation/verify       POST — Razorpay verification
 */
export function registerV1Routes(app: Express): void {
  app.use("/api/v1", securityRouter);
  app.use("/api/v1/qr", qrRouter);
  app.use("/api/v1/donation", paymentsRouter);
}

