          makeScanEntry(content, qr.contentType, qr.id, scanSource)
        );
      }
      recordScanEvent(qr.id, {
        platform: _getPlatform(),
        contentType: qr.contentType,
        verdict,
        scanSource,
      }).catch(() => {});
    } catch {}
  })();
}

